import json
d=json.load(open('layout.json'))

def walk(n, out):
    if isinstance(n, dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='codeVoice': out.append('`'+n.get('code','')+'`')
        elif t=='table':
            out.append('\n[TABLE]\n')
            for row in n.get('rows',[]):
                cells=[]
                for c in row:
                    sub=[]
                    for x in c: walk(x,sub)
                    cells.append(''.join(sub).strip())
                out.append(' | '.join(cells)+'\n')
            out.append('[/TABLE]\n')
            return
        elif t=='heading':
            out.append('\n\n## '+n.get('text','')+'\n')
            return
        elif t=='paragraph':
            for x in n.get('inlineContent',[]): walk(x,out)
            out.append('\n')
            return
        for k,v in n.items():
            if k in ('references','metadata','hierarchy'): continue
            walk(v,out)
    elif isinstance(n,list):
        for x in n: walk(x,out)

out=[]
walk(d.get('primaryContentSections'),out)
txt=''.join(out)
open('layout.txt','w').write(txt)
print(txt)
